const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-slack-request-timestamp'];
const slackSignature = headers['x-slack-signature'];
const signingSecret = $env.SLACK_SIGNING_SECRET;

if (!timestamp || !slackSignature || !signingSecret) {
  throw new Error('missing Slack signature headers or SLACK_SIGNING_SECRET');
}

// Slack recommends rejecting anything older than ~5 minutes to block replay attacks.
const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - Number(timestamp)) > 60 * 5) {
  throw new Error('Slack request timestamp is stale (possible replay)');
}

// Requires the Webhook node's "Raw Body" option — Slack signs the exact raw
// bytes, and a re-stringified parsed body will not match byte-for-byte.
const rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const baseString = `v0:${timestamp}:${rawBody}`;
const expectedSignature =
  'v0=' + crypto.createHmac('sha256', signingSecret).update(baseString).digest('hex');

const provided = Buffer.from(slackSignature);
const expected = Buffer.from(expectedSignature);
if (provided.length !== expected.length || !crypto.timingSafeEqual(provided, expected)) {
  throw new Error('invalid Slack signature');
}

const payload = JSON.parse(item.json.body.payload);
const action = payload.actions && payload.actions[0];
if (!action) {
  throw new Error('no action in Slack interaction payload');
}

const decision =
  action.action_id === 'leadflow_approve'
    ? 'approve'
    : action.action_id === 'leadflow_reject'
      ? 'reject'
      : null;
if (!decision) {
  throw new Error(`unrecognized action_id: ${action.action_id}`);
}

return [
  {
    json: {
      leadId: action.value,
      decision,
      responseUrl: payload.response_url,
      userName: (payload.user && payload.user.username) || null,
    },
  },
];
